from AlgorithmImports import *
from collections import deque
import math


class PrivateLotStrategyAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = [self.add_equity(ticker, Resolution.DAILY).symbol
                        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]]
        self.spy = self.symbols[0]
        self.aapl = self.symbols[1]

        self.sma_period = 20
        self.spy_sma = self.sma(self.spy, self.sma_period, Resolution.DAILY)
        self.aapl_rsi = self.rsi(self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY)

        self.spy_closes = deque(maxlen=2)
        self.aapl_closes = deque(maxlen=4)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def on_data(self, data: Slice):
        if any(symbol not in data.bars for symbol in self.symbols):
            return

        spy_close = data.bars[self.spy].close
        aapl_close = data.bars[self.aapl].close

        prior_spy_close = self.spy_closes[-1] if self.spy_closes else None
        prior_sma = self.spy_sma.current.value if self.spy_sma.is_ready else None

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if not self.spy_sma.is_ready or not self.aapl_rsi.is_ready:
            return
        if len(self.spy_closes) < 2 or len(self.aapl_closes) < 4:
            return

        current_sma = self.spy_sma.current.value
        previous_sma = prior_sma

        if previous_sma is None:
            return

        # Sells before buys.
        if self.strategy_a_lot > 0:
            if prior_spy_close <= previous_sma and spy_close < current_sma:
                self.market_order(self.spy, -self.strategy_a_lot)
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.aapl, -self.strategy_b_lot)
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0:
            if prior_spy_close <= previous_sma and spy_close > current_sma:
                quantity = int(math.floor(
                    0.40 * self.portfolio.total_portfolio_value / spy_close
                ))
                if quantity > 0:
                    self.market_order(self.spy, quantity)
                    self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0:
            closes = list(self.aapl_closes)
            if closes[-1] < closes[-2] and closes[-2] < closes[-3] and closes[-3] < closes[-4]:
                if self.portfolio.cash >= 20_000:
                    quantity = int(math.floor(20_000 / aapl_close))
                    if quantity > 0:
                        self.market_order(self.aapl, quantity)
                        self.strategy_b_lot = quantity

