from AlgorithmImports import *

class PrivateLotStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = [
            self.AddEquity("SPY", Resolution.Daily).Symbol,
            self.AddEquity("AAPL", Resolution.Daily).Symbol,
            self.AddEquity("IBM", Resolution.Daily).Symbol,
            self.AddEquity("BAC", Resolution.Daily).Symbol,
            self.AddEquity("AIG", Resolution.Daily).Symbol
        ]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.ma_period = 50
        self.spy_closes = RollingWindow[float](self.ma_period + 1)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        if any(symbol not in data.Bars for symbol in self.symbols):
            self._update_market_state(data)
            return

        self._update_market_state(data)

        if not self._rules_ready():
            return

        # Evaluate sells before buys.
        if self.strategy_a_shares > 0 and self._spy_crosses_below_ma():
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self._spy_crosses_above_ma():
            close = self.Securities[self.spy].Price
            shares = int((self.Portfolio.TotalPortfolioValue * 0.40) / close)
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self._aapl_red_for_three_days():
            close = self.Securities[self.aapl].Price
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 / close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

    def _update_market_state(self, data: Slice):
        if self.spy in data.Bars:
            self.spy_closes.Add(float(data.Bars[self.spy].Close))

        if self.aapl in data.Bars:
            self.aapl_closes.Add(float(data.Bars[self.aapl].Close))

    def _rules_ready(self):
        return (
            self.spy_closes.IsReady
            and self.aapl_closes.IsReady
            and self.aapl_rsi.IsReady
        )

    def _spy_crosses_above_ma(self):
        current_close = self.spy_closes[0]
        previous_close = self.spy_closes[1]

        current_ma = sum(self.spy_closes[i] for i in range(self.ma_period)) / self.ma_period
        previous_ma = sum(self.spy_closes[i] for i in range(1, self.ma_period + 1)) / self.ma_period

        return previous_close <= previous_ma and current_close > current_ma

    def _spy_crosses_below_ma(self):
        current_close = self.spy_closes[0]
        previous_close = self.spy_closes[1]

        current_ma = sum(self.spy_closes[i] for i in range(self.ma_period)) / self.ma_period
        previous_ma = sum(self.spy_closes[i] for i in range(1, self.ma_period + 1)) / self.ma_period

        return previous_close >= previous_ma and current_close < current_ma

    def _aapl_red_for_three_days(self):
        return (
            self.aapl_closes[0] < self.aapl_closes[1]
            and self.aapl_closes[1] < self.aapl_closes[2]
            and self.aapl_closes[2] < self.aapl_closes[3]
        )

