        previous_spy_ma = float(self.spy_ma.current.value) if self.spy_ma.is_ready else None
        previous_rsi = float(self.aapl_rsi.current.value) if self.aapl_rsi.is_ready else None

        self.spy_closes.add(spy_close)
        self.aapl_closes.add(aapl_close)

        if not self.spy_ma.is_ready or not self.aapl_rsi.is_ready:
            return
        if self.spy_closes.count < 2 or self.aapl_closes.count < 4:
            return

        previous_spy_close = self.spy_closes[1]
        current_spy_ma = float(self.spy_ma.current.value)

        # Sells before buys.
        if self.strategy_a_shares > 0:
            if previous_spy_close >= previous_spy_ma and spy_close < current_spy_ma:
                self.market_order(self.spy, -self.strategy_a_shares)
