class ParallelStrategySystem(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_rsi = self.rsi(self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def on_data(self, data: Slice):
        for symbol in self.symbols.values():
            if data.bars.contains_key(symbol):
                close = float(data.bars[symbol].close)
                if symbol == self.spy:
                    self.spy_closes.add(close)
                elif symbol == self.aapl:
                    self.aapl_closes.add(close)

        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        if not (self.spy_closes.is_ready and self.aapl_closes.is_ready and self.aapl_rsi.is_ready):
            return

        spy_close = self.spy_closes[0]
        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        spy_crosses_above = self.spy_closes[1] <= spy_sma_yesterday and spy_close > spy_sma_today
        spy_crosses_below = self.spy_closes[1] >= spy_sma_yesterday and spy_close < spy_sma_today

        aapl_red_three_days = all(
            self.aapl_closes[i] < self.aapl_closes[i + 1]
            for i in range(3)
        )

        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.market_on_close_order(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.current.value > 60:
            self.market_on_close_order(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            shares = int((0.40 * float(self.portfolio.total_portfolio_value)) // spy_close)
            if shares > 0:
                self.market_on_close_order(self.spy, shares)
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and aapl_red_three_days:
            aapl_close = self.aapl_closes[0]
            if self.portfolio.cash >= 20_000:
                shares = int(20_000 // aapl_close)
                if shares > 0:
                    self.market_on_close_order(self.aapl, shares)
                    self.strategy_b_lot = shares

