class ParallelSpyAaplAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = [
            self.add_equity("SPY", Resolution.DAILY).symbol,
            self.add_equity("AAPL", Resolution.DAILY).symbol,
            self.add_equity("IBM", Resolution.DAILY).symbol,
            self.add_equity("BAC", Resolution.DAILY).symbol,
            self.add_equity("AIG", Resolution.DAILY).symbol,
        ]

        self.spy = self.symbols[0]
        self.aapl = self.symbols[1]

        self.spy_sma = self.sma(self.spy, 100, Resolution.DAILY)
        self.aapl_rsi = self.rsi(self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY)

        self.close_windows = {
            symbol: RollingWindow[float](101)
            for symbol in self.symbols
        }

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.aapl_red_streak = 0

    def on_data(self, data: Slice):
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols):
            return

        closes = {symbol: data.bars[symbol].close for symbol in self.symbols}

        previous_aapl_close = (
            self.close_windows[self.aapl][0]
            if self.close_windows[self.aapl].count > 0
            else None
        )

        if previous_aapl_close is not None:
            if closes[self.aapl] < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_windows_ready = all(
            window.count >= 101 for window in self.close_windows.values()
        )
        rules_ready = (
            all_windows_ready
            and self.spy_sma.is_ready
            and self.aapl_rsi.is_ready
        )

        if rules_ready:
            spy_close_today = closes[self.spy]
            spy_close_yesterday = self.close_windows[self.spy][0]
            spy_sma_today = self.spy_sma.current.value
            spy_sma_yesterday = sum(
                self.close_windows[self.spy][i]
                for i in range(1, 101)
            ) / 100.0

            spy_crossed_below = (
                spy_close_yesterday >= spy_sma_yesterday
                and spy_close_today < spy_sma_today
            )
            aapl_rsi_above_60 = self.aapl_rsi.current.value > 60

            if self.strategy_a_shares > 0 and spy_crossed_below:
                self.market_order(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if self.strategy_b_shares > 0 and aapl_rsi_above_60:
                self.market_order(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

            spy_crossed_above = (
                spy_close_yesterday <= spy_sma_yesterday
                and spy_close_today > spy_sma_today
            )

            if self.strategy_a_shares == 0 and spy_crossed_above:
                shares = int(
                    (self.portfolio.total_portfolio_value * 0.40) / spy_close_today
                )
                if shares > 0:
                    self.market_order(self.spy, shares)
                    self.strategy_a_shares = shares

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                aapl_close = closes[self.aapl]
                if self.portfolio.cash >= 20_000:
                    shares = int(20_000 / aapl_close)
                    if shares > 0:
                        self.market_order(self.aapl, shares)
                        self.strategy_b_shares = shares

        for symbol in self.symbols:
            self.close_windows[symbol].add(closes[symbol])

