from AlgorithmImports import *

class SpecifiedStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        if any(symbol not in data.Bars or data.Bars[symbol] is None for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        prior_spy_close = self.previous_spy_close
        prior_spy_sma = self.previous_spy_sma
        prior_aapl_close = self.previous_aapl_close

        self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
        self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if prior_aapl_close is None:
            self.aapl_red_streak = 0
        elif aapl_bar.Close < prior_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        fully_formed = (
            self.spy_sma.IsReady and
            self.aapl_rsi.IsReady and
            prior_spy_close is not None and
            prior_spy_sma is not None and
            prior_aapl_close is not None
        )

        if fully_formed:
            # Sells before buys; slots operate independently in parallel.
            if self.strategy_a_lot > 0:
                if prior_spy_close <= prior_spy_sma and spy_bar.Close < self.spy_sma.Current.Value:
                    self.MarketOrder(self.spy, -self.strategy_a_lot)
                    self.strategy_a_lot = 0

            if self.strategy_b_lot > 0:
                if self.aapl_rsi.Current.Value > 60:
                    self.MarketOrder(self.aapl, -self.strategy_b_lot)
                    self.strategy_b_lot = 0

            if self.strategy_a_lot == 0:
                if prior_spy_close <= prior_spy_sma and spy_bar.Close > self.spy_sma.Current.Value:
                    shares = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_bar.Close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)
                        self.strategy_a_lot = shares

            if self.strategy_b_lot == 0:
                if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20000:
                    shares = int(20000 // aapl_bar.Close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.strategy_b_lot = shares

        self.previous_spy_close = spy_bar.Close
        self.previous_spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
        self.previous_aapl_close = aapl_bar.Close

