from AlgorithmImports import *


class IndependentSlotsAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_close = {}
        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        received = {}
        for ticker, symbol in self.symbols.items():
            if symbol in data.Bars:
                received[ticker] = data.Bars[symbol]

        # Market-state quantities continue updating whenever their own data exists.
        if "SPY" in received:
            spy_close = received["SPY"].Close
            if self.spy_sma.IsReady:
                current_sma = self.spy_sma.Current.Value
                if self.spy_previous_close is not None and self.spy_previous_sma is not None:
                    spy_values_ready = True
                else:
                    spy_values_ready = False
            else:
                current_sma = None
                spy_values_ready = False
        else:
            spy_close = None
            current_sma = None
            spy_values_ready = False

        if "AAPL" in received:
            aapl_close = received["AAPL"].Close
            prior_aapl_close = self.previous_close.get(self.aapl)
            if prior_aapl_close is not None:
                if aapl_close < prior_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
        else:
            aapl_close = None

        # All rules are skipped unless every subscribed ticker has today's bar.
        complete_day = len(received) == len(self.symbols)
        if complete_day:
            # Sells before buys: Strategy A
            if self.strategy_a_shares > 0 and spy_values_ready:
                crosses_below = (
                    self.spy_previous_close >= self.spy_previous_sma
                    and spy_close < current_sma
                )
                if crosses_below:
                    self.MarketOrder(self.spy, -self.strategy_a_shares)
                    self.strategy_a_shares = 0

            # Sells before buys: Strategy B
            if self.strategy_b_shares > 0 and self.aapl_rsi.IsReady:
                if self.aapl_rsi.Current.Value > 60:
                    self.MarketOrder(self.aapl, -self.strategy_b_shares)
                    self.strategy_b_shares = 0

            # Buys: Strategy A
            if self.strategy_a_shares == 0 and spy_values_ready:
                crosses_above = (
                    self.spy_previous_close <= self.spy_previous_sma
                    and spy_close > current_sma
                )
                if crosses_above:
                    quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_close)
                    if quantity > 0:
                        self.MarketOrder(self.spy, quantity)
                        self.strategy_a_shares = quantity

            # Buys: Strategy B
            if (
                self.strategy_b_shares == 0
                and self.aapl_rsi.IsReady
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_shares = quantity

        # Store closes after evaluating today's rules.
        for ticker, bar in received.items():
            self.previous_close[self.symbols[ticker]] = bar.Close

        if "SPY" in received and self.spy_sma.IsReady:
            self.spy_previous_close = spy_close
            self.spy_previous_sma = current_sma

