            return

        for symbol in self.symbols:
            self.closes[symbol].append(float(data.Bars[symbol].Close))

        self.aapl_rsi.Update(data.Bars[self.aapl].EndTime, data.Bars[self.aapl].Close)

        if len(self.closes[self.spy]) < 101 or not self.aapl_rsi.IsReady:
            return

