        spy_ma_today = sum(spy_closes[-100:]) / 100.0

        aapl_closes = list(self.closes[self.aapl])
        aapl_red_3_days = (
            aapl_closes[-1] < aapl_closes[-2] and
            aapl_closes[-2] < aapl_closes[-3] and
            aapl_closes[-3] < aapl_closes[-4]
        )

        # Sells before buys
        if self.strategy_a_shares > 0:
            if spy_close_yesterday >= spy_ma_yesterday and spy_close_today < spy_ma_today:
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            if spy_close_yesterday <= spy_ma_yesterday and spy_close_today > spy_ma_today:
                shares = int(math.floor((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close_today))
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and aapl_red_3_days:
            if self.Portfolio.Cash >= 20000:
                aapl_close = float(data.Bars[self.aapl].Close)
                shares = int(math.floor(20000 / aapl_close))
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

