        previous_spy_close = self.spy_closes[-1] if len(self.spy_closes) > 0 else None

        if self.aapl_previous_close is not None:
            if aapl_bar.Close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.aapl_rsi.Update(IndicatorDataPoint(self.Time, aapl_bar.Close))
        self.spy_closes.append(spy_bar.Close)

        if len(self.spy_closes) < 101 or not self.aapl_rsi.IsReady:
            self.aapl_previous_close = aapl_bar.Close
            return

        spy_values = list(self.spy_closes)
        yesterday_ma = sum(spy_values[:-1]) / 100.0
        today_ma = sum(spy_values[1:]) / 100.0

        spy_crosses_above_ma = (
            previous_spy_close <= yesterday_ma and
            spy_bar.Close > today_ma
        )
        spy_crosses_below_ma = (
            previous_spy_close >= yesterday_ma and
            spy_bar.Close < today_ma
        )

        # Sells are evaluated before buys.
        if self.lots["A"] > 0 and spy_crosses_below_ma:
            self.MarketOrder(self.spy, -self.lots["A"])
            self.lots["A"] = 0

        if self.lots["B"] > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.lots["B"])
            self.lots["B"] = 0

        if self.lots["A"] == 0 and spy_crosses_above_ma:
            quantity = floor(0.40 * self.Portfolio.TotalPortfolioValue / spy_bar.Close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.lots["A"] = quantity

