                            self.aapl_red_streak = 0

                    self.aapl_previous_close = bar.Close

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if (not self.spy_sma.IsReady or
                self.spy_sma_values.Count < 2 or
                not self.aapl_rsi.IsReady or
                self.aapl_previous_close is None):
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        previous_sma = self.spy_sma_values[1]
        current_sma = self.spy_sma_values[0]

        spy_crosses_below_sma = (
            self.strategy_a_lot > 0 and
            previous_sma <= self.spy_sma_values[1] and
            spy_close < current_sma and
            float(self.spy_sma_values[1]) <= previous_sma
        )

        if self.strategy_a_lot > 0:
            previous_spy_close = None
            if self.Time.date() != self.StartDate.date():
                previous_spy_close = spy_close

            if self.spy_sma_values.Count == 2:
                prior_close_above_or_equal = False
                if hasattr(self, "previous_spy_close"):
                    prior_close_above_or_equal = self.previous_spy_close >= previous_sma

                if prior_close_above_or_equal and spy_close < current_sma:
                    self.MarketOrder(self.spy, -self.strategy_a_lot)
                    self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0:
            prior_close_below_or_equal = (
                hasattr(self, "previous_spy_close") and
                self.previous_spy_close <= previous_sma
            )

            if prior_close_below_or_equal and spy_close > current_sma:
                quantity = int(float(self.Portfolio.TotalPortfolioValue) * 0.40 / spy_close)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

        self.previous_spy_close = spy_close
